import { get, handleApiError, post } from '@helpers/httpClient';

import { mapBackUserPhoneToFront } from '../@mappers/user.mappers';
import {
  IUserFoodStatisticDTO,
  IUserPhoneDTO,
  IUserProfileDTO,
  IUserYearStatisticDTO,
} from '../@types/user.types';

export const getUserStatisticByYear = (id_user: number, year = new Date().getFullYear()) => {
  return get('/ajax/users/statistic/year.php', { id_user: id_user, year }).then<
    IUserYearStatisticDTO[]
  >(handleApiError);
};

export const getUserFoodStatisticByYear = (id_user: number, year = new Date().getFullYear()) => {
  return get('/ajax/users/statistic/food.php', { id_user, year }).then<IUserFoodStatisticDTO[]>(
    handleApiError,
  );
};

export async function getUserPhones() {
  const data = await get('/ajax/users/phones/phones_list.php').then<IUserPhoneDTO[]>(
    handleApiError,
  );

  return data.map(mapBackUserPhoneToFront);
}

export async function addOrUpdateUserPhone(data: IUserPhoneDTO) {
  return post('/ajax/users/phones/phones_add.php', data).then<{ id?: number; success: boolean }>(
    handleApiError,
  );
}
export async function deleteUserPhone(id: number) {
  return post('/ajax/users/phones/phones_del.php', { id }).then<{ success: boolean }>(
    handleApiError,
  );
}
export async function testUserPhone(id: number) {
  return post('/ajax/users/phones/phones_test.php', { id }).then<{
    status: string;
    balance: number;
  }>(handleApiError);
}

export const getProfileInfo = () => {
  return get('/ajax/profile/profile_get_all.php').then<IUserProfileDTO>(handleApiError);
};

type PossibleKey =
  | 'email'
  | 'name'
  | 'surname'
  | 'dob'
  | 'ava'
  | 'address'
  | 'phone'
  | 'skype'
  | 'icq'
  | 'weight'
  | 'growth'
  | 'id_region'
  | 'photo_50'
  | 'photo_100'
  | 'photo_200_orig'
  | 'photo_max'
  | 'photo_max_orig'
  | 'uniq_code'
  | 'inaturalist_login';

export type UserProfileDataPatch = Partial<Record<PossibleKey, any>>;
export const updateCurrentUserFields = (path: UserProfileDataPatch) => {
  return post('/ajax/users/user_save_param.php', path).then(handleApiError);
};
